import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷二","description":"周易经传集解 - 周易经传集解卷二","frontmatter":{"title":"周易经传集解卷二","description":"周易经传集解 - 周易经传集解卷二"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/003.md","filePath":"zh/classics/jingchuan-jijie/003.md"}'),r={name:"zh/classics/jingchuan-jijie/003.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷二",tabindex:"-1"},[n("周易经传集解卷二 "),e("a",{class:"header-anchor",href:"#周易经传集解卷二","aria-label":"Permalink to “周易经传集解卷二”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解卷二 ​宋林栗撰。序卦曰：「有天地，然后万物生焉。盈天地之间者惟万物，故受之以屯。屯者，盈也；屯者，物之始生也。」屯之成卦，变坤之初、五二爻而成也。变者何也？乾交于坤，故其象不得不变也。天地不交，万物不生。乾坤既成列矣，必自其始交而言之。始交而成震，震在下而始然重卦之象，非三画之震所能备也。若取诸重震，则非始交之义也。故自其交以至于通而言之。始通而成坎，坎在中为通。始乎震，通乎坎，物之所生也，故谓之屯。屯者，盈也，万物盈乎天地之间者也。万，盈数也，数之积也。自一至十，天地之数，而屯之画具矣。屯者，物之始生也。物生之始，形质未定，其数已盈乎天地之间矣。是何也？震坎之中有坤艮之象焉。坤也者，万物之所致养也。艮也者，万物之所成终而成始也。则其盈满天地，不亦宜乎？夫子所作十翼，先儒既取其释彖、大小象、文言分系于经，学者便于寻绎。自汉以来，未之有改，而独系辞、说卦、序卦、杂卦至今为完篇。夫说卦止于八物，而系辞领略纲纪，固不可得而分系之矣。若夫序、杂二篇，条陈其用，无所遗漏，宜与象彖同其离合，然而不之取者，序卦皆相因，杂卦皆相交。相因之义，近于浅易，相交之辞，几于隐者，是以学者难言之，而又疑其未必然也。未必然者，妄也。杨雄有言曰：「圣人之言天也。」岂妄乎？夫序卦者，卦之所以相推而立也；杂卦者，卦之所以相错而成也。相推故相因，相错故相交，是六十四卦之所从出也。今将寻其流，探其源，而不知派之所从别，可乎？虽然，理则万殊，其归一揆，既曰相因，又曰相交，何也？曰：相因如一二，相交如奇偶。一之与二，乃其所以为奇偶，故不同于雅、颂、典、谟、训诰之书。于其本篇，各冠以夫子之序，独遗易而不取者，惑也。愚故仿彖、象之例，取序卦一篇，自屯而下，释于逐卦之首，而杂卦之义，辨于爻象之前。至于本篇，自如其旧，学者得以考焉。屯：元亨利贞，勿用有攸往，利建侯。彖曰：屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。称天地之德曰「乾坤」，称乾坤之德曰「元亨利贞」，无以加于此矣。屯之成卦，震下坎上，而称其德亦曰「元亨利贞」，何也？曰：屯也者，乾坤变而其气通也，是乃其所以为乾坤者也。其称之盛，不亦宜乎？或曰：「震坎成卦而取诸乾坤以为义。」夫六十四象，孰非乾坤者？而「元亨利贞」独称于屯、临、随、无妄、革，何也？曰：之数卦者，各有其义，未暇悉数也。若夫屯者，震坎之所成也。震坎成而坤艮著，然后屯象立也。「震」为元，「坎」为亨、为利，「艮」为贞，始终之义备也。天气下降，地气上腾，乾之象见于三子，坤之象备于三爻，生成之义无不备矣。是故兼乎四德而称之也。夫子释之，言「大」而不言「元」，明其所自来也；言「亨」而不言「利」，明其兼之也。可谓晦而章矣。然而「勿用有攸往」，何也？曰：「震」一阳在下为始，又为动；坎一阳在中为通，又为险、为陷。故曰：「刚柔始交而难生，动乎险中。」夫险难在前，见利而动，未有无悔者也。故戒之曰：「勿用有攸往。」然而「利建侯」，何也？曰：「坤」者，乾之配也，代乾之主也。「震」、「坎」、「艮」者，乾之子也，成乾之用也。是故先王建邦设都，立之司牧，以长治之，君人者不劳而天下治矣，焉用攸往哉？夫「乾」之彖曰「元亨利贞」，而不曰「有攸往」者，君道也。「坤」之彖曰「元亨，利牝马之贞，君子有攸往」者，臣道也。屯之彖曰「元亨利贞，勿用有攸往，利建侯」者，合而言之也。天下归往谓之王，受君之民而为之牧，谓之侯伯。若皆不往，则险难无自而济矣。故曰：「雷雨之动满盈，天造草昧，宜建侯而不宁。」夫天之所为者，茫昧而不可知，其可见者，雷雨满盈而已。是以「勿用有攸往」，而「利建侯」也。或曰：子以四象为义，而夫子之释「彖曰」，但言雷雨而不及坤、艮，何哉？曰：夫子不云乎，易有四象，所以示也。夫震、坎者，所以为屯也。既已为屯矣，虽不言震、坎，可也。是故文王、周公但言屯而未尝言震、坎也。坤也者，震、坎之所致养；艮者，震、坎之所终始也。既已为震、坎矣，虽不言坤、艮，可也。是故夫子言震、坎，而未尝言坤、艮也。斯不亦举一隅之意乎？学者苟以为不然，则震、坎之所以为屯，屯之所以为元、亨、利、贞，吾不知其何从而得此象，又系之以如此之辞也。象曰：云雷，屯，君子以经纶。「云雷」，「坎」、「震」也。「云雷」者，所以为雨也。方其未雨也，满盈乎天地之间，是以谓之屯也。君子观此屯之象，以经纶天下之事业，犹云与雷动，而膏泽随之也。经纶之为言，组织之未成云尔。然经之纶之，所以为组织也，其亦云雷而未雨之义乎？或曰：云雨皆坎也，不谓之雨而谓之云，何也？曰：雨在雷上，雷至雨未至，是以谓之云也。然而其彖又曰：「云雷之动满盈。」何也？曰：云为雨而未成者也，谓之雷雨之动，不亦可乎？既雨则解矣，而何满盈之有哉？杂卦曰：「屯见而不失其居。」自坤而屯，初与五变，而三不变也。变于初而配在四，变于五而配在二，何不屯之有哉？三上不变，莫适为配，是其所以为屯也。三变则为既济矣。夫阴阳相求，物之情也。三，阳位也。在屯之世，刚柔始交，民无定主，以六居之，能无争乎？是以为屯。六三求于上六而弗之应，介于二四而莫之与，二将应五，四将应初，三为之难，是以谓之屯也。夫天无二日，民无二王，使三而不为之难，彼为二阳者，亦莫能相抑也。是故初以四为配而承于二，五以二为配而比于四，据两立之𫝑，挟猜疑之情，其为屯难，不亦宜乎？然初与四、二与五，皆不失其正，而二五又中也。其在爻，初四有婚媾之利，二五有小大之屯，何也？曰：天地交而为泰，不交则为否。乾下于四，坤升于四，是以为见也。九五在上，六二在下，是以为屯也。此所谓见而不失其居者乎？初九：磐桓，利居贞，利建侯。象曰：虽「磐桓」，志行正也。以贵下贱，大得民也。初九，「震」也，以阳居刚，而在下卦之初，应乎六四而承乎六二，二爻皆「坤」，而四又「坎」也，故曰「磐桓」。说者谓「磐桓」为回旋，失之矣。夫磐如磐，桓如桓。磐，大石也；桓，大木也。石磐于地，故谓之「磐」。易曰：「鸿渐于磐。」木亘于地，故谓之「桓」。诗曰「松柏桓桓」是也。「磐桓」与「介于石」之义同，谓居贞也。或曰：震为动、为躁，而取「磐桓」以为义，然则「艮」之象于何取之？曰：「艮」者，震之所自来也；震者，艮之所从出也。艮终而震始，艮少而震长。是故震为大涂，而艮为小石；震为苍筤，而艮为坚节；震为重门，而艮为门阙，皆相因之义也。「豫」之六二，介于石者，「艮」也。其不终日者，出乎「震」也。今也震居坤下，三阴乘之，犹未离乎「艮」也，谓之「磐桓」，不亦宜乎？夫静不极者其动不威，守不固者其发不勇，根不深者其末不茂，基不大者其上不广。故曰：「利居贞，利建侯。」以九居初，正也。君子居得其正，民之所归，是以能「建侯」也。居天下之广居，行天下之大道，是之谓「居贞」也。有天下而君之，列爵分土，法制号令，我之自出，是以谓「建侯」也。故曰：「譬如北辰，居其所而众星拱之。」彖所谓「勿用有攸往」是也。震为长男，有天子象；「坤」为臣妾，有诸侯万民之象。方屯之初，婚媾未定，男不下女，无以得妻；君不下士，无以得臣。初九以阳下阴，以贵下贱，卑𫝑而尊贤，先人而后己，民之归之，如水之就下。是故初体乎「震」，不得不上行；四体乎「坎」，不得不就下；上体乎「坤」，不得不顺服。是以得民而建候也。故曰：「虽磐桓，志行正也；以贵下贱，大得民也。」六三，屯如邅如，乘马班如，匪寇婚媾。女子贞不字，十年乃字。象曰：六二之难，乘刚也。「十年乃字」，反常也。六二，「坤」也。以阴居柔，而在下卦之中，应于九五而乘乎初九，二爻皆「震」也。承于六三，三则「艮」也，故曰「屯如邅如」。屯，难也。邅，回而不进也，故曰「乘马班如」。春秋传曰：「有班马之声。」杜氏曰：「班，别也。」乾为马，马，阳物也。震、坎、艮得乾之一体，是以皆称之也。二之如初，非其所乘，是故有「班马」之象。古者大事不乘异产。「乘马班如」，其欲去之亟矣。然五在险中，四为之难，三方守之正，三遏其冲，故曰：「匪寇婚媾，女子贞不字。」四与上皆「坎」也，「坎」为盗，故有寇象。二五平应，匪寇之故，则「婚媾」矣。「婚媾」也者，言其以正合也。「女子」者，未嫁之称也。六五居中守正，故有「女子」之象。然体「坤」而配五，又有为母之道焉。「字」，母道也。「婚媾」则「字」矣。既曰「婚媾」，又曰「不字」，何也？曰：夫妇之道，男先女，女乃从之；君臣之义，君先下士，士乃应之。合六五体震而止行，不肯下逮六二体坤而后和，莫敢先求。又有二爻实为之间，故虽「婚媾」既成，犹「十年」而「不字」也。夫士之仕，犹女之嫁也，不曰「士贞」而曰「女子贞」者，女子待礼而行，贞而不可犯，于士为犹严也。虽牝牡之情、室家之愿，阳唱而阴和，男行而女从，自然之理也。方屯之时，阴阳相求，三字六正而有五为之配，其终「不字」而已乎？故曰：「十年乃字。」十者，数之终也，大运之行也。数终必变，运周必复。二五相易，「婚媾」字矣。雷雨作解，其十年之数乎？故子曰：「六二之难，乘刚也。十年乃字，反常也。」六三：即鹿无虞，惟入于林中。君子几，不如舍，往吝。象曰：「即鹿无虞」，以从禽也。君子舍之，「往吝」穷也。六三以阴居刚，而在下卦之上，上体为「艮」，下体亦为「艮」，而介乎二四之坤，应在上六，上为坎，又阴象也。故曰：「即鹿无虞，惟入于林中」。「震」「坎」重而「坤」「艮」具，动乎险中，所以为屯也。坎「艮」成而隐伏，鹿之象也。「坤」为众，林中之象也。三非阳也，而居于刚，自以为阳，而求配于上六。六不之应，而介乎二四之间，无德而求民者也。平世之民，以鱼为喻，乱世之民，以鹿为喻，善走而难驯也。山林榛莽，兽之窟宅，虞人知之。无德而求民，犹无虞而即鹿也。夫初九之为六二，皆有其德而得其配，故以婚媾言之。诗曰：「娶妻如之何？匪媒不得。」取之有媒，犹田之有虞也。故田者必以虞人为指。苟无虞而田，无媒而娶，皆寇也。故曰：「君子舍之，往吝穷也」。舍，止也。吝，羞也。「艮」在坎下，见险而能止者也。即鹿而无虞，鹿不可得，而入于林莽之中矣。苟贪利而忘义，险在前而不顾，其自取困穷之羞，不亦宜乎？故子曰：「即鹿无虞，以从禽也。君子舍之，往吝穷也。」或云：别本「以从禽也」上有「何」字，当从之。「君子舍之往吝」为句。六四：乘马班如，求婚媾。往吉，无不利。象曰：求而往，明也。六四以阴居柔，而在上卦之下，上体为「坎」，下体为「坤」，应乎初九之「震」，而乘六三之「艮」，故曰「乘马班如」。屯惟二阳，而三爻皆言「乘马」者，明三体「艮」而居刚，有为君之志也。四配在初而乘乎三，以其所乘，故亦有「班如」之象也。「乘马班如」，则必舍之而从初矣，故曰「求婚媾」。「往」，求初也。往者四也。男先下女，女乃从之；君先下士，士乃应之。求而不往则失君，不求而往则失臣，二者皆过也。初九以阳而下阴，体「震」而上行，先求之义也。六四以阴而从阳，体「坎」而就下，后往之义也。故曰：「吉无不利。」男女皆正而家以肥，君臣皆正而国以治，如是之「吉」，而有不利乎哉？故子曰：「求而往，明也。」君臣之间，夫妇之际，而可以不明乎哉？初九「震」为「明」，六三「艮」为幽。二爻见求，而四之所往者明也。九五：屯其膏，小贞吉，大贞凶。象曰：「屯其膏」，施未光也。九五，「震」也，以阳居刚而在上卦之中，应乎六二之「坤」，而乘承皆「坎」也，故曰：「屯其膏」。「震」为雷，「坎」为雨，膏泽之象也。「坤」为主，为民，震为上行，膏泽不下于下之象也。五配在二，而莫肯相求，是以屯其膏而不下也。阳为大，阴为小。大者，五也，君道也，夫道也；小者，二也，妻道也，臣道也。五，正也，二亦正也。然女不求男，不失其为女；士不求君，不失其为士。小者以是为正，则吉矣。男不下女，旡以成其家；君不下士，旡以保其国。大者以是为正，莫之与矣。欲旡凶，得乎？故初与五同于体「震」，二与四同于体「坤」，谓之「婚媾」，而或利或屯者，升降之不同也。然云雷之盈，其终必雨。二五反常，「十年乃字」，其雷雨作解之象乎？故子曰：「屯其膏，施未光也。」上六：乘马班如，泣血涟如。象曰：「泣血涟如」，何可长也？上六之象，以阴居柔，而在上卦之上，应在六三而乘九五之「震」，故曰「乘马班如」。上之与五，非其所乘，故亦有「班如」之象。然二舍其班而适五，四舍其班而适初，各从其偶也。上六舍其班而适三，三阴柔而体「艮」，非其偶也，故曰「泣血涟如」。「坎」为忧伤，为心病，为血卦，故有「泣血」之象。上六正反皆「坎」，则「涟如」之象也。居屯之极，与五为邻，舍之而去，怅怅然旡所之，途穷泣血，不亦宜乎？序卦曰：屯者，物之始生也。物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。蒙之成卦，屯之反也。覆而视屯，蒙之象也。乾坤之交，由震而达乎坎，由坎而终乎艮，则屯蒙之序也。夫蒙者，冥昧之称也，掩蔽之义也。万物之生，受阴阳之气，杂乎芒芴之间，谓之屯。勾萌胎卵，有生而未达，襁褓覆翼，有识而未开，则谓之蒙。不屯则不生，不蒙则不成。是故屯之彖曰：「元亨，利贞。」蒙之彖不曰「元」而曰「亨利贞」，于义昭矣。蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。彖曰：蒙，山下有险，险而止，蒙。蒙亨，以亨行，时中也。匪我求童蒙，童蒙求我，志应也。初筮告，以刚中也；再三渎，渎则不告，渎蒙也。蒙以养正，圣功也。下坎上震，成卦曰「蒙」者，坎为水，艮为山，坤为地，艮为山，为止。水出于地而山止之，故谓之蒙。险陷之中，进而上行，有物止而蒙之象也。夫子但取其二象而释之曰：「山下有险，险而止，蒙。」夫险能不出，此其所以为蒙也。是故谓之「童蒙」，谓之「蒙暗」，谓之「蒙蔀」。今曰「蒙亨」，何也？曰：蒙亨，蒙而求亨也，非谓蒙者有时而亨也。凡物之生，形气未定，无以蒙之，则暴露散越而不能以条畅遂茂。人之聪明亦如是尔。仁、义、礼、智，性所有也。发而不中节，则流而入于邪。养之以正，若火之始然，泉之始达矣。故曰：「蒙亨，以亨行，时中也。」以亨行者，因其𫝑而利导之，非揠苗而助之长也。发而中节，不亦宜乎？匪我求童蒙，童蒙求我。何也？曰：蒙之诸爻，以上蒙下为义。其二阳，先觉之象；其四阴，童蒙之象也。阳为明，阴为晦；上为应，下为求。初六之蒙，九二发之；六五之蒙，上九击之。童蒙求我也。三之不顺，四之独远，匪我求童蒙也。君子之教也，来者弗距，去者弗追，人之求我，斯应之矣。彼不我求，吾曷为即之哉？故曰：「匪我求童蒙，童蒙求我，志应也。」志于应而已，不志于求也。初筮告，再三渎，渎则不告。初之与二，五之与上，求则得之，皆初筮也。三四之于上，历二三爻，求而弗应，再三渎也。筮者，所以求疑也，齐戒以奉之，肃恭以临之，弗敢渎之。初筮而不从，又求改筮，至于再，至于三，神弗之告矣。诗云：「我龟既厌，不我告犹。」君子之教也，与其进，不与其退。人洁已以进，斯告之矣。不愤不启，不悱不发，学而弗志，问而弗思，诲尔谆讳，听我藐藐，又从而告之，祗所以渎之也。故曰：「初筮告，以刚中也。」「再三渎，渎则不告」，渎蒙也。或曰：二之位，刚中固也。上九亦曰「刚中」，何哉？曰：此之谓时中也。初六以不中而震坤遇险而止，所以为蒙也。今因蒙之初，以阴求九二，故九二以中而发之。六五之童蒙，未失乎中也，故上九为之「御寇」而已。「御寇」者，闲邪之义也。然则九二之为「刚中」，六五之谓「时中」，其于初筮告，以亨行，均也。夫子之言，盖互明矣。「利贞」，何也？曰：亨而利，利而正，乾坤之序也。通乎坎，成乎艮，故系之也。喜怒哀乐未发，谓之中，发而皆中节，谓之和。惟精惟一，允执厥中。故曰：「蒙以养正，圣功也。」洪范：「圣，时风若；蒙，恒风若。」夫圣与蒙反象也，可不深求其义乎？象曰：山下出泉，蒙；君子以果行育德。山，艮也；泉，坎也。坎不曰「水」而曰「泉」者，水在山下，泉之象也。泉出于山，土石蒙之，其源滥觞，其及远也，无所不至，故君子以之「果行育德」。「果行」者，犹其不舍昼夜也；「育德」者，犹其源深而流长也。孟子曰：「源泉混混，不舍昼夜。」盈科而后进，放乎四海。有本者如是，是之取尔。其山下出泉，果行育德之义乎？杂卦曰：「蒙杂而著。」蒙者，蒙也。蒙之言覆也，故爻以上蒙下为义。日出而明，入而晦，故阳为明，阴为蒙。蒙者必求于人，求人者未有不下之者也。故下为求，上为应。中也养不中，才也养不才。故以阳居柔者，人之所求也。若以阳居刚，则为独善其身，非蒙之所赖也。以阴居柔，刚困而不举者，终于蒙而已矣。故曰：「蒙杂而著」，此之谓也。今夫蒙者，「坎」「艮」之所成也。坎为幽，比方之卦也；艮为土，东北之卦也。自坎而徂艮，则为蒙；自艮而徂震，则为明矣。然则坎从艮，非求艮也，将以求震也。震也者，艮之反也。入乎坎而不止乎艮，则何以能出乎震哉？是故蒙之阴爻，「坎」、「坤」、「艮」也；其阳爻，皆「震」也。此则童蒙之所以来我者也。或问：「说卦：离为明，今谓震为明，何也？」曰：「离也者，日中之明也；震也者，日出之明也。蒙之求明，犹夜之求旦也，而岂日中为义乎？」初六：发蒙，利用刑人，用说桎梏，以往，吝。象曰：「利用刑人」，以正法也。初六，「坎」也。以阴居刚，而在一卦之下，承于九二之震，其应六四，四则「艮」也，故曰「发蒙」。坎为幽，震为明，以幽求明，发蒙之象也。在卦之下，下愚之品，聪明不开，恣于情欲，放僻邪侈，无不为矣，故曰：「利用刑人。」阴为刑，坎为陷，陷于刑者，皆蒙象也。震为动，为决躁。刑，刑人之象也。夫不教而杀，谓之虐，今蒙之初，不教而刑之，何也？曰：阳为德，阳为刑。震主施惠，坎主幽陷，阳以坎从震，用刑辅德者也，故曰「利」。利也者，非以刑杀人为利也，制为之刑，以杜其非心，加之明刑，以冀其悛革，斯为利也。若有罪而刑杀，又何利之有哉？或曰：刑一人而千万人服，岂非利乎？曰：不然者也。刑所以利民也，非毒民而以自利也。若刑杀人、劓人，刑人而我以为利，是诚何心哉？故曰「用说桎梏以往」。各坎为矫𫐓，故有「桎梏」之象。震为出，故有说而往之象。荀氏说卦：「坎为桎梏。」桎梏者，所以械其首足也。夫用刑，然后说之以往。周官：大司寇以圜土聚教罢民，见害人者，弗为寇饰，而加明刑焉。其不能改而出圜土者，杀。又以嘉石平罢民，凡民之有罪而未丽于法者，桎梏而坐诸嘉石，役诸司空，使州里任之，然后宥而舍之。所谓「说桎梏以往」者，不能改而出圜土者也。于是而用刑焉，一成而不可变者也。死者不能复生，断者不可复续，圣人之所不忍也，故曰「吝」。立法制用于加桎梏之前，可谓利矣。刑杀劓用于「说桎梏」之后，亦有吝乎？「吝」之言「羞」者，夫岂特罢民之羞？为政者不能使民迁善改恶，而至于用刑，亦可羞矣。故子曰：「利用刑人，以正法也。」舜之命皋陶曰：「汝作士，明于五刑，以弼五教，期予于治。」刑期于无刑者也。甫刑曰：「伯夷降典，折民惟刑。」「士制百姓于刑之中，以教祗德。」皆正法之谓也，而岂以刑杀人为利哉？九二：包蒙，吉。纳妇，吉，子克家。象曰：「子克家」，刚柔接也。九二，「震」也。以阳居柔而在下卦之中，应乎六五而介于初、三，二爻皆「坎」，而三又「坤」也，故曰「包蒙」。「包」，覆藏也。「坎」为隐伏，故有「包蒙」之象。以阳明之资，震动之体，而在阴柔险陷之中，以蒙自包者也。君子之道，「暗然而日章」，有诸中而形诸外，故曰「吉」。然乘乎初六，有发蒙之象，故又曰：「纳妇吉」。「妇」谓初也。妇之初归，未习夫家之事，童蒙也纳而教之，正法以刑之，辨之于早，不亦「吉」乎？诗曰：「刑于寡妻。」书曰：「观厥刑于二女。」皆此之谓也。故曰「子克家」。「震」，长子也，能教其妇，斯克其家矣。或曰：「二配在五，不以五为妇乎？」曰：「蒙以上下为义，五居尊，非妇也。」曰：「然则六五为父，九二为子乎？」曰：非也。对子而言，则父刚而子柔。今子克家，而父为童蒙，吾未之闻矣。父在，观其志；父没，观其行。今父在而言克家，吾亦未之闻矣。曰：然则九二何从而称子乎？曰：五体「坤」，「坤」为母，阴柔居尊，群蒙所附，非得九二刚中之子，何以克其家乎？故子曰：「克家，刚柔接也。」言九二以刚明之才，上接六五而任其任；六五以柔顺之德，下接九二而行其道，是以能克家也。「坎」六四之象曰「刚柔际」者，明二爻之象。此言「刚柔接」者，明上下之象也。岂一时之苟指哉？六三：勿用取女，见金夫，不有躬，无攸利。象曰：「勿用取女」，行不顺也。六三上体为「坤」，下体为「坎」，以阴居刚而在下卦之上，应乎上九而乘乎九二，二爻皆「震」也。承于六四，四则「艮」也，故曰：「勿用取女」。以阴居刚，体「坤」而「离」乎「坎」，近九二而下比之，女之不可取者也，故曰：「见金夫，不有躬，无攸利」。「金」者，刚也。三之称金，犹其称马也，皆得「乾」之一体故也。夫之吉，配也。三配在上而比于二，见刚夫而求之，不自有其身者，女之丑行也。败国乱家，皆是物也，何所往而利哉？或曰：何以知三之不待配而从二乎？曰：为其「坎」也。坎为水，水性趋下而乘乎二，其求之也，孰御之哉？故子曰：「勿用取女，行不顺也。」三体「坤」，「坤」为顺。今杂乎「坎」而为不顺之行，是以圣人戒之也。六四：困蒙，吝。象曰：困蒙之「吝」，独远实也。六四正反皆「艮」也。以阴居柔而在上卦之下，介于三、五之间。三与五皆「坤」，而初与二皆「坎」也，故曰「困蒙」。「坤」为黑，「坎」为幽，「艮」为止，相与为暗昧者也。困而不举，斯为下矣。杨雄有言：「侍于君子，晦斯光，窒斯通。」今六四以阴柔之质，而上下无阳，不能近乎君子矣。其困不亦宜乎？故曰「吝」。书曰：「远耆德，比顽童。」是已。子曰：「困蒙之吝，独远实也。」阳为实，阴为虚。实，故有以分人；虚，故可以受道。六四以阴居柔，而在三阴之中，独远于阳，宜其吝也。六五：童蒙，吉。象曰：「童蒙」之吉，顺以巽也。六五，「坤」也，以阴居刚而在上卦之中，隐乎九二而承于上九，二爻皆震也，故曰「童蒙」。坤为顺，震为明，以顺求明，「童蒙」之象也。礼曰：「喜怒哀乐未发之谓中。」六五是也。或曰：「六五之蒙，有以异于初六乎？」曰：是何言与？初居最下，下德之质也；五居尊位，而以中行，上智之资也。上智之资而谓之「童蒙」，何也？曰：童蒙者，求人也。礼恭，然后可以言道之方；辞顺，然后可以言道之理；色从，然后可以言道之致。夫如是，四海之内，皆将轻千里而来告之以善，故曰「吉」。高宗之诰曰：「以台正于四方，台恐德弗类。」成王之诰曰：「维予小子，不聪敬止。」此之谓「童蒙」也。终始典于学，厥修德罔觉，日就月将，学有缉熙于光明，斯之谓「吉」矣。子曰：童蒙之吉，顺以巽也。「坤」为顺，因其𫝑而利导之，非勉强而行之者也。故夫九二、上九皆「震」也，而初六则「坎」也，六五则「坤」也。「坤」为黑，「坎」为幽，其为蒙一也。而「坎」为险，坤为顺，此其所以不同欤？或曰：子以初为下愚，五为上智，三、四者，中人之性欤？曰：然。然则中人以下，六三是也；中人以上，六四是也。曷为其困且吝也？曰：三舍顺而效逆，四远贤而比愚，其不可以语上，均矣。困且吝，宜哉！上九：击蒙，不利为寇，利御寇。象曰：利用「御寇」，上下顺也。上九，「震」也。以阳居柔，而在一卦之上，应于六三而乘乎六五，二爻皆「坤」，而三又「坎」也，故曰「击蒙」。说者皆以「击蒙」为征伐之义，非也。夫既谓之蒙矣，虽不帅教，岂能得与我敌也哉？教之弗帅，君子犹矜其愚而将宥之，不得已而后刑之，则初六之「刑人」是也。何至于与师动众，以力胜之乎？或曰：然则击蒙何义也？曰：击如击鼓、击磬之击。阳者，阴之所求也；明者，暗之所求也。「震」为声，为动，故有击蒙之象。瞽者不见泰山，聋者不闻雷霆，下愚之质也。发之而后耳有闻，目有见。初六谓之发蒙，叩之小则小鸣，叩之大则大鸣，上智之资也。触之而无不应，故六五谓之「童蒙」。夫五以柔居尊，委听于上，其终为圣、为蒙，在上九所以击之何如耳？故曰：「不利为寇，利御寇。」格其非心，引之于当道，所谓「御寇」也；逢君之恶，纳之于邪，所谓为寇也。有御寇之臣，则五为信顺尚贤之君。有为寇之臣，则五为暗弱失权之主。然则当其任者，其非伊传周公而谁可乎？管蔡之流言曰：「公不利于孺子。」此则为寇也。「周公东征，四国是皇。」此则御寇也。孟子曰：「有伊尹之志则可，无伊尹之志，则篡也。」或曰：上九一爻，兼有为寇、御寇之象乎？曰：有之。六三，坎也。坎为寇，有不顺之行，上与之配，若不从之，是与之为寇矣。拒而不以刑御之，何以知其有利不利乎？曰：三以小人而乘君子之器，既无攸利矣。上而从之，又何利之有焉？故三言「勿用取女」，上言「不利为寇」，可谓深切著明矣。子曰：「利用御寇，上下顺也。」上为六五，下为六三，上下二爻皆有坤顺之体。故上九系之而无不应，御之而无不服。功成于外，而人主不疑；委任于中，而天下不议。此非人臣之利，天下国家之利也。六五不顺，虽欲御寇，不可得矣；六三不顺，虽欲击蒙，又可得乎？周公所以居东三年，而作鸱鹗之诗，以遗成王也。周易经传集解卷二，",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
